import { useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { AgendaLista } from '../components/agenda/AgendaLista';
import { AgendamentoForm } from '../components/agenda/AgendamentoForm';
import { AlertaVencimentos } from '../components/agenda/AlertaVencimentos';
import { BaixaForm } from '../components/agenda/BaixaForm';
import { CalendarioGrade } from '../components/agenda/CalendarioGrade';
import { ResumoAgenda } from '../components/agenda/ResumoAgenda';
import { ConfirmDialog } from '../components/ConfirmDialog';
import { Alerta, Botao, Cartao, CampoTexto, EstadoVazio, TituloPagina } from '../components/ui';
import {
  agendamentosDoMes,
  alertaVencimentos,
  criarAgendamentos,
  excluirAgendamento,
  marcarComoPago,
  reabrirAgendamento,
  totaisAgenda,
} from '../domain/agenda';
import { hojeISO, mesValido, nomeMes, somarMeses } from '../domain/date';
import type { Agendamento } from '../domain/types';
import { useEstado, useStore } from '../state/store';
import '../components/agenda/agenda.css';

export function CalendarioPage() {
  const store = useStore();
  const estado = useEstado();
  const [params, setParams] = useSearchParams();
  const [erro, setErro] = useState<string | null>(null);
  const [pagando, setPagando] = useState<Agendamento | null>(null);
  const [excluindo, setExcluindo] = useState<Agendamento | null>(null);
  const hoje = hojeISO();

  const mesParam = params.get('mes') ?? '';
  const mes = mesValido(mesParam) ? mesParam : hoje.slice(0, 7);
  const itens = agendamentosDoMes(estado, mes);
  const nomesCategorias = new Map(estado.categorias.map((c) => [c.id, c.nome]));
  const irPara = (novo: string) => mesValido(novo) && setParams({ mes: novo }, { replace: true });

  const executar = (operacao: Parameters<typeof store.aplicar>[0], falhaMsg: string) => {
    const r = store.aplicar(operacao);
    setErro(r.ok ? null : r.erro || falhaMsg);
    return r.ok;
  };

  return (
    <div>
      <TituloPagina>Calendário</TituloPagina>
      <div className="agenda-pagina">
        {erro ? <Alerta>{erro}</Alerta> : null}

        <Cartao titulo="Vencimentos próximos">
          <AlertaVencimentos alerta={alertaVencimentos(estado, hoje)} />
        </Cartao>

        <Cartao titulo="Novo lançamento">
          <AgendamentoForm categorias={estado.categorias} contas={estado.contas} onSalvar={(dados) => store.aplicar((s) => criarAgendamentos(s, dados))} />
        </Cartao>

        <Cartao>
          <div className="agenda-navegacao">
            <Botao variante="secundario" onClick={() => irPara(somarMeses(mes, -1))}>
              Mês anterior
            </Botao>
            <div className="agenda-navegacao-mes">
              <CampoTexto label="Mês" type="month" value={mes} onChange={(e) => irPara(e.target.value)} />
            </div>
            <Botao variante="secundario" onClick={() => irPara(somarMeses(mes, 1))}>
              Próximo mês
            </Botao>
          </div>
        </Cartao>

        <Cartao titulo={`Totais de ${nomeMes(mes)}`}>
          <ResumoAgenda totais={totaisAgenda(itens)} />
        </Cartao>

        <Cartao titulo={`Calendário de ${nomeMes(mes)}`}>
          <CalendarioGrade mes={mes} itens={itens} hoje={hoje} />
        </Cartao>

        {pagando ? (
          <Cartao titulo={`Marcar como pago: ${pagando.descricao}`}>
            <BaixaForm
              key={pagando.id}
              item={pagando}
              categorias={estado.categorias}
              contas={estado.contas}
              onConfirmar={(dados) => {
                const r = store.aplicar((s) => marcarComoPago(s, pagando.id, dados));
                if (r.ok) {
                  setPagando(null);
                  setErro(null);
                }
                return r;
              }}
              onCancelar={() => setPagando(null)}
            />
          </Cartao>
        ) : null}

        <Cartao titulo="Lançamentos do mês">
          {estado.agenda.length === 0 ? (
            <EstadoVazio titulo="Nenhum lançamento agendado">Cadastre contas a pagar e a receber acima para acompanhar os vencimentos.</EstadoVazio>
          ) : itens.length === 0 ? (
            <p className="agenda-texto-suave">Nenhum lançamento com vencimento neste mês.</p>
          ) : (
            <AgendaLista
              itens={itens}
              hoje={hoje}
              nomesCategorias={nomesCategorias}
              onPagar={(a) => setPagando(a)}
              onReabrir={(a) => executar((s) => reabrirAgendamento(s, a.id), 'Não foi possível reabrir o lançamento.')}
              onExcluir={(a) => setExcluindo(a)}
            />
          )}
        </Cartao>
      </div>

      {excluindo ? (
        <ConfirmDialog
          titulo="Excluir lançamento"
          mensagem={`Excluir "${excluindo.descricao}"? A transação de um pagamento já feito não é apagada.`}
          rotuloConfirmar="Excluir"
          perigo
          onConfirmar={() => {
            const alvo = excluindo;
            setExcluindo(null);
            if (pagando?.id === alvo.id) setPagando(null);
            executar((s) => excluirAgendamento(s, alvo.id), 'Não foi possível excluir o lançamento.');
          }}
          onCancelar={() => setExcluindo(null)}
        />
      ) : null}
    </div>
  );
}
import { diasDaGrade, situacaoAgendamento } from '../../domain/agenda';
import type { Agendamento, DataISO, Mes } from '../../domain/types';
import './agenda.css';

const SEMANA = ['dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb'];
const CLASSE = { pago: 'agenda-cal-item-pago', atrasado: 'agenda-cal-item-atrasado', pendente: 'agenda-cal-item-pendente' };
const ROTULO = { pago: 'Pago', atrasado: 'Atrasado', pendente: 'Pendente' };

interface Props {
  mes: Mes;
  itens: Agendamento[];
  hoje: DataISO;
}

/** Grade mensal (domingo a sábado) com os lançamentos de cada dia. */
export function CalendarioGrade({ mes, itens, hoje }: Props) {
  const dias = diasDaGrade(mes);
  return (
    <div className="agenda-cal-rolagem">
      <div className="agenda-cal" role="group" aria-label="Calendário do mês">
        {SEMANA.map((d) => (
          <div key={d} className="agenda-cal-semana">
            {d}
          </div>
        ))}
        {dias.map((data, i) =>
          data === null ? (
            <div key={`vazio-${i}`} aria-hidden="true" />
          ) : (
            <div
              key={data}
              data-testid={`dia-${data}`}
              className={`agenda-cal-dia${data === hoje ? ' agenda-cal-dia-hoje' : ''}`}
            >
              <span className="agenda-cal-numero">{Number(data.slice(8, 10))}</span>
              <ul className="agenda-cal-lista">
                {itens
                  .filter((a) => a.vencimento === data)
                  .map((a) => {
                    const situacao = situacaoAgendamento(a, hoje);
                    return (
                      <li key={a.id} className={`agenda-cal-item ${CLASSE[situacao]}`} title={`${a.descricao} (${ROTULO[situacao]})`}>
                        {a.descricao} <span className="agenda-cal-situacao">· {ROTULO[situacao]}</span>
                      </li>
                    );
                  })}
              </ul>
            </div>
          ),
        )}
      </div>
    </div>
  );
}
import type { TotaisAgenda } from '../../domain/agenda';
import { formatarMoeda } from '../../domain/money';
import './agenda.css';

export function ResumoAgenda({ totais }: { totais: TotaisAgenda }) {
  const linhas: [string, number, string][] = [
    ['A pagar', totais.aPagar, 'total-a-pagar'],
    ['A receber', totais.aReceber, 'total-a-receber'],
    ['Já pago', totais.jaPago, 'total-ja-pago'],
    ['Já recebido', totais.jaRecebido, 'total-ja-recebido'],
  ];
  return (
    <dl className="agenda-resumo">
      {linhas.map(([rotulo, valor, id]) => (
        <div key={id}>
          <dt className="agenda-resumo-rotulo">{rotulo}</dt>
          <dd className="agenda-resumo-valor" data-testid={id}>
            {formatarMoeda(valor)}
          </dd>
        </div>
      ))}
    </dl>
  );
}
/* Agenda / Calendário: CSS puro com tokens de design. */
.agenda-pagina { display: grid; gap: var(--esp-4); }

.agenda-alertas { display: grid; gap: var(--esp-2); }
.agenda-texto-suave { margin: 0; font-size: var(--texto-sm); color: var(--cor-texto-suave); }
.agenda-num { font-variant-numeric: tabular-nums; }

.agenda-lista { margin: 0; padding: 0; list-style: none; }
.agenda-item {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between;
  gap: var(--esp-2); padding: var(--esp-2) 0; font-size: var(--texto-sm);
}
.agenda-item + .agenda-item { border-top: 1px solid var(--cor-borda); }
.agenda-item-texto { min-width: 0; }
.agenda-item-titulo { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 500; color: var(--cor-texto); }
.agenda-item-detalhe { font-size: var(--texto-xs); color: var(--cor-texto-suave); }
.agenda-item-acoes { display: flex; flex-wrap: wrap; align-items: center; gap: var(--esp-2); }

.agenda-proximos { margin: 0; padding: 0; list-style: none; font-size: var(--texto-sm); }
.agenda-proximo { display: flex; justify-content: space-between; gap: var(--esp-2); padding: var(--esp-1) 0; }
.agenda-proximo + .agenda-proximo { border-top: 1px solid var(--cor-borda); }

.agenda-form { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--esp-3); }
.agenda-form-linha { grid-column: 1 / -1; }
.agenda-form-botoes { display: flex; flex-wrap: wrap; gap: var(--esp-2); }
@media (min-width: 640px) {
  .agenda-form-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .agenda-form-4 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (min-width: 1024px) {
  .agenda-form-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}

.agenda-navegacao { display: flex; flex-wrap: wrap; align-items: flex-end; gap: var(--esp-3); }
.agenda-navegacao-mes { width: 11rem; max-width: 100%; }

.agenda-resumo { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--esp-3); margin: 0; font-size: var(--texto-sm); }
.agenda-resumo > div { min-width: 0; }
.agenda-resumo-rotulo { color: var(--cor-texto-suave); }
.agenda-resumo-valor { margin: 0; font-size: var(--texto-lg); font-weight: 700; overflow-wrap: anywhere; }
@media (min-width: 1024px) { .agenda-resumo { grid-template-columns: repeat(4, minmax(0, 1fr)); } }

.agenda-badge { display: inline-block; border-radius: var(--raio-total); padding: 0.125rem var(--esp-2); font-size: var(--texto-xs); font-weight: 600; }
.agenda-badge-pago { background: var(--cor-sucesso-suave); color: var(--cor-sucesso); }
.agenda-badge-atrasado { background: var(--cor-perigo-suave); color: var(--cor-perigo); }
.agenda-badge-pendente { background: var(--cor-aviso-suave); color: var(--cor-aviso); }

/* Grade mensal: rola dentro do próprio contêiner em telas estreitas (sem rolagem da página). */
.agenda-cal-rolagem { overflow-x: auto; max-width: 100%; }
.agenda-cal { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: var(--esp-1); min-width: 42rem; font-size: var(--texto-xs); }
.agenda-cal-semana { padding: 0 var(--esp-1); text-align: center; font-weight: 600; text-transform: uppercase; color: var(--cor-texto-suave); }
.agenda-cal-dia { min-height: 5rem; min-width: 0; border: 1px solid var(--cor-borda); border-radius: var(--raio-pequeno); padding: var(--esp-1); background: var(--cor-superficie); }
.agenda-cal-dia-hoje { border-color: var(--cor-primaria); background: var(--cor-primaria-suave); }
.agenda-cal-numero { display: block; font-weight: 600; color: var(--cor-texto); }
.agenda-cal-lista { display: grid; gap: 0.125rem; margin: 0; padding: 0; list-style: none; }
.agenda-cal-item { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; border-left: 4px solid; border-radius: 0.25rem; padding: 0 var(--esp-1); background: var(--cor-superficie-alt); color: var(--cor-texto); }
.agenda-cal-item-pago { border-left-color: var(--cor-sucesso); }
.agenda-cal-item-atrasado { border-left-color: var(--cor-perigo); }
.agenda-cal-item-pendente { border-left-color: var(--cor-aviso); }
.agenda-cal-situacao { color: var(--cor-texto-suave); }

