import { useMemo, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { ConfirmDialog } from '../components/ConfirmDialog';
import { DividaForm } from '../components/dividas/DividaForm';
import { PagamentoDividaForm } from '../components/dividas/PagamentoDividaForm';
import { ResumoDivida } from '../components/dividas/ResumoDivida';
import { SimuladorDividas } from '../components/dividas/SimuladorDividas';
import { TabelaAmortizacao } from '../components/dividas/TabelaAmortizacao';
import { ROTULO_SISTEMA, rotulosTipo } from '../components/dividas/rotulos';
import { Alerta, Botao, CampoSelect, Cartao, EstadoVazio, TituloPagina } from '../components/ui';
import { formatarData, hojeISO } from '../domain/date';
import { criarDivida, excluirDivida, excluirPagamentoDivida, registrarPagamentoDivida, resumoDivida } from '../domain/dividas';
import { formatarMoeda, valorParaCampo } from '../domain/money';
import { useEstado, useStore } from '../state/store';
import '../components/dividas/dividas.css';

export function DividasPage() {
  const store = useStore();
  const estado = useEstado();
  const [params, setParams] = useSearchParams();
  const [erro, setErro] = useState<string | null>(null);
  const [confirmando, setConfirmando] = useState(false);
  const hoje = hojeISO();

  const divida = estado.dividas.find((d) => d.id === params.get('divida')) ?? estado.dividas[0];
  const resumo = useMemo(() => (divida ? resumoDivida(divida, hoje) : null), [divida, hoje]);
  const rotulos = divida ? rotulosTipo(divida.tipo) : null;

  /** Para ações sem formulário (exclusões): o erro vai para o alerta da página. */
  const aplicar = (operacao: Parameters<typeof store.aplicar>[0]) => {
    const r = store.aplicar(operacao);
    setErro(r.ok ? null : r.erro);
  };

  return (
    <div>
      <TituloPagina>Dívidas e empréstimos</TituloPagina>
      <div className="dividas-pagina">
        {erro ? <Alerta>{erro}</Alerta> : null}

        {!divida || !resumo || !rotulos ? (
          <EstadoVazio titulo="Nenhuma dívida cadastrada">
            Cadastre um financiamento ou empréstimo para acompanhar parcelas, juros e saldo, ou use o simulador abaixo.
          </EstadoVazio>
        ) : (
          <>
            <Cartao>
              <div className="dividas-seletor">
                <div className="dividas-seletor-campo">
                  <CampoSelect label="Dívida" value={divida.id} onChange={(e) => setParams({ divida: e.target.value })}>
                    {estado.dividas.map((d) => (
                      <option key={d.id} value={d.id}>
                        {d.nome}
                      </option>
                    ))}
                  </CampoSelect>
                </div>
                <Botao variante="perigo" onClick={() => setConfirmando(true)}>
                  Excluir dívida
                </Botao>
              </div>
              <p className="dividas-termos" data-testid="termos">
                {divida.tipo === 'devo' ? 'Eu devo' : 'Eu emprestei'} {formatarMoeda(divida.principal)} · {valorParaCampo(divida.taxaBp)}% ao mês · {divida.parcelas}x · {ROTULO_SISTEMA[divida.sistema]} ·
                1ª parcela em {formatarData(divida.primeiraParcela)}
              </p>
            </Cartao>

            <Cartao titulo="Resumo">
              <ResumoDivida resumo={resumo} tipo={divida.tipo} />
            </Cartao>

            <Cartao titulo="Tabela de amortização">
              <TabelaAmortizacao linhas={resumo.linhas} />
            </Cartao>

            <Cartao titulo={`${rotulos.pagamento}s registrados`}>
              {divida.pagamentos.length > 0 ? (
                <ul className="dividas-pagamentos" aria-label={`${rotulos.pagamento}s registrados`}>
                  {divida.pagamentos.map((p) => (
                    <li key={p.id} className="dividas-pagamento">
                      <span>
                        {formatarData(p.data)} · {p.parcela === undefined ? 'Amortização extra' : `Parcela ${p.parcela}`} · {formatarMoeda(p.valor)}
                      </span>
                      <Botao
                        variante="secundario"
                        aria-label={`Excluir ${rotulos.pagamento.toLowerCase()} de ${formatarData(p.data)}`}
                        onClick={() => aplicar((s) => excluirPagamentoDivida(s, divida.id, p.id))}
                      >
                        Excluir
                      </Botao>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="dividas-texto-suave dividas-espaco-baixo">Nenhum {rotulos.pagamento.toLowerCase()} registrado.</p>
              )}
              {resumo.quitada ? (
                <p className="dividas-texto-suave">Não há saldo em aberto.</p>
              ) : (
                <PagamentoDividaForm
                  key={`${divida.id}-${divida.pagamentos.length}`}
                  tipo={divida.tipo}
                  abertas={resumo.linhas.filter((l) => l.situacao !== 'paga')}
                  onSalvar={(dados) => store.aplicar((s) => registrarPagamentoDivida(s, divida.id, dados, hoje))}
                />
              )}
            </Cartao>
          </>
        )}

        <Cartao titulo="Nova dívida ou empréstimo">
          <DividaForm onSalvar={(dados) => store.aplicar((s) => criarDivida(s, dados))} />
        </Cartao>

        <Cartao titulo="Simulador Price x SAC">
          <SimuladorDividas />
        </Cartao>
      </div>

      {confirmando && divida ? (
        <ConfirmDialog
          titulo="Excluir dívida"
          mensagem={`Excluir "${divida.nome}" e todos os seus pagamentos? Esta ação não pode ser desfeita.`}
          rotuloConfirmar="Excluir"
          perigo
          onCancelar={() => setConfirmando(false)}
          onConfirmar={() => {
            setConfirmando(false);
            setParams({}, { replace: true });
            aplicar((s) => excluirDivida(s, divida.id));
          }}
        />
      ) : null}
    </div>
  );
}
import { useState, type FormEvent } from 'react';
import { parseTaxaBp, simular, validarTermos, type ResumoSimulacao } from '../../domain/dividas';
import { formatarMoeda, parseValor } from '../../domain/money';
import type { SistemaAmortizacao } from '../../domain/types';
import { Botao, CampoTexto } from '../ui';
import { NOME_SISTEMA } from './rotulos';
import './dividas.css';

type Erros = Partial<Record<'principal' | 'taxa' | 'parcelas', string>>;
type Resultado = Record<SistemaAmortizacao, ResumoSimulacao>;

/** Compara Price e SAC lado a lado; nada é salvo. */
export function SimuladorDividas() {
  const [principal, setPrincipal] = useState('');
  const [taxa, setTaxa] = useState('');
  const [parcelas, setParcelas] = useState('');
  const [erros, setErros] = useState<Erros>({});
  const [resultado, setResultado] = useState<Resultado | null>(null);

  const enviar = (e: FormEvent) => {
    e.preventDefault();
    const termos = {
      principal: parseValor(principal) ?? Number.NaN,
      taxaBp: parseTaxaBp(taxa) ?? Number.NaN,
      parcelas: parcelas.trim() === '' ? Number.NaN : Number(parcelas),
    };
    const v = validarTermos(termos);
    if (!v.ok) {
      setResultado(null);
      return setErros({ [v.campo ?? 'principal']: v.erro });
    }
    setErros({});
    setResultado(simular(termos));
  };

  return (
    <div>
      <form onSubmit={enviar} noValidate aria-label="Simulador" className="dividas-form dividas-form-3">
        <CampoTexto label="Principal a simular" value={principal} onChange={(e) => setPrincipal(e.target.value)} erro={erros.principal} inputMode="decimal" placeholder="0,00" />
        <CampoTexto label="Taxa mensal a simular (%)" value={taxa} onChange={(e) => setTaxa(e.target.value)} erro={erros.taxa} inputMode="decimal" placeholder="1,99" />
        <CampoTexto label="Prazo a simular (parcelas)" value={parcelas} onChange={(e) => setParcelas(e.target.value)} erro={erros.parcelas} inputMode="numeric" />
        <div className="dividas-form-linha">
          <Botao type="submit">Simular</Botao>
        </div>
      </form>
      {resultado ? (
        <div className="dividas-simulacao" aria-label="Resultado da simulação">
          {(['price', 'sac'] as const).map((s) => (
            <section key={s} aria-label={`Simulação ${NOME_SISTEMA[s]}`} className="dividas-simulacao-cartao">
              <h3 className="dividas-simulacao-titulo">{NOME_SISTEMA[s]}</h3>
              <dl className="dividas-simulacao-dados">
                <dt className="dividas-rotulo">Primeira parcela</dt>
                <dd className="dividas-num dividas-direita" data-testid={`sim-${s}-primeira`}>{formatarMoeda(resultado[s].primeiraParcela)}</dd>
                <dt className="dividas-rotulo">Última parcela</dt>
                <dd className="dividas-num dividas-direita" data-testid={`sim-${s}-ultima`}>{formatarMoeda(resultado[s].ultimaParcela)}</dd>
                <dt className="dividas-rotulo">Total de juros</dt>
                <dd className="dividas-num dividas-direita" data-testid={`sim-${s}-juros`}>{formatarMoeda(resultado[s].totalJuros)}</dd>
                <dt className="dividas-rotulo">Total pago</dt>
                <dd className="dividas-num dividas-direita" data-testid={`sim-${s}-total`}>{formatarMoeda(resultado[s].totalPago)}</dd>
              </dl>
            </section>
          ))}
        </div>
      ) : null}
    </div>
  );
}
import { useEffect, useId, useRef, useState } from 'react';
import { Botao, CampoTexto } from './ui';
import './ConfirmDialog.css';

interface Props {
  titulo: string;
  mensagem: string;
  rotuloConfirmar: string;
  perigo?: boolean;
  /** Se informado, o usuário precisa digitar exatamente este texto para confirmar. */
  textoDigitado?: string;
  onConfirmar: () => void;
  onCancelar: () => void;
}

/** Diálogo modal de confirmação. Renderize-o apenas quando estiver aberto. */
export function ConfirmDialog({ titulo, mensagem, rotuloConfirmar, perigo, textoDigitado, onConfirmar, onCancelar }: Props) {
  const idTitulo = useId();
  const [digitado, setDigitado] = useState('');
  const raiz = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const alvo = raiz.current?.querySelector<HTMLElement>('input, button');
    alvo?.focus();
  }, []);

  useEffect(() => {
    const aoTeclar = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onCancelar();
    };
    document.addEventListener('keydown', aoTeclar);
    return () => document.removeEventListener('keydown', aoTeclar);
  }, [onCancelar]);

  const liberado = textoDigitado === undefined || digitado === textoDigitado;

  return (
    <div className="ui-modal-fundo">
      <div ref={raiz} role="dialog" aria-modal="true" aria-labelledby={idTitulo} className="ui-modal">
        <h2 id={idTitulo} className="ui-modal__titulo">
          {titulo}
        </h2>
        <p className="confirm-mensagem">{mensagem}</p>
        {textoDigitado !== undefined ? (
          <div className="confirm-campo">
            <CampoTexto label={`Digite ${textoDigitado} para confirmar`} value={digitado} onChange={(e) => setDigitado(e.target.value)} autoComplete="off" />
          </div>
        ) : null}
        <div className="confirm-acoes">
          <Botao variante="secundario" onClick={onCancelar}>
            Cancelar
          </Botao>
          <Botao variante={perigo ? 'perigo' : 'primario'} disabled={!liberado} onClick={onConfirmar}>
            {rotuloConfirmar}
          </Botao>
        </div>
      </div>
    </div>
  );
}
